import{_ as l,a0 as t,w as d,s as o,ao as r,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"df 命令新手教程 | LCTT x X-CMD","titleTemplate":false,"description":"df 命令新手教程 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"df 命令新手教程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"df 命令新手教程 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180413 The df Command Tutorial With Examples For Beginners","title":"df 命令新手教程","tag":"201810","desc":""},"relativePath":"201810/20180413 The df Command Tutorial With Examples For Beginners.md","filePath":"[post].md"}'),c={name:"201810/20180413 The df Command Tutorial With Examples For Beginners.md"};function h(f,s,u,m,g,b){const n=t("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="df-命令新手教程" tabindex="-1">df 命令新手教程 <a class="header-anchor" href="#df-命令新手教程" aria-label="Permalink to “df 命令新手教程”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/04/df-command-1-720x340.png" alt=""></p><p>在本指南中，我们将学习如何使用 <code>df</code> 命令。df 命令是 “Disk Free” 的首字母组合，它报告文件系统磁盘空间的使用情况。它显示一个 Linux 系统中文件系统上可用磁盘空间的数量。<code>df</code> 命令很容易与 <code>du</code> 命令混淆。它们的用途不同。<code>df</code> 命令报告我们拥有多少磁盘空间（空闲磁盘空间），而 <code>du</code> 命令报告被文件和目录占用了多少磁盘空间。希望我这样的解释你能更清楚。在继续之前，我们来看一些 <code>df</code> 命令的实例，以便于你更好地理解它。</p><h3 id="df-命令使用举例" tabindex="-1">df 命令使用举例 <a class="header-anchor" href="#df-命令使用举例" aria-label="Permalink to “df 命令使用举例”">​</a></h3><h4 id="_1、查看整个文件系统磁盘空间使用情况" tabindex="-1">1、查看整个文件系统磁盘空间使用情况 <a class="header-anchor" href="#_1、查看整个文件系统磁盘空间使用情况" aria-label="Permalink to “1、查看整个文件系统磁盘空间使用情况”">​</a></h4><p>无需任何参数来运行 <code>df</code> 命令，以显示整个文件系统磁盘空间使用情况。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Filesystem 1K-blocks Used Available Use% Mounted on</span></span>
<span class="line"><span>dev 4033216 0 4033216 0% /dev</span></span>
<span class="line"><span>run 4038880 1120 4037760 1% /run</span></span>
<span class="line"><span>/dev/sda2 478425016 428790352 25308980 95% /</span></span>
<span class="line"><span>tmpfs 4038880 34396 4004484 1% /dev/shm</span></span>
<span class="line"><span>tmpfs 4038880 0 4038880 0% /sys/fs/cgroup</span></span>
<span class="line"><span>tmpfs 4038880 11636 4027244 1% /tmp</span></span>
<span class="line"><span>/dev/loop0 84096 84096 0 100% /var/lib/snapd/snap/core/4327</span></span>
<span class="line"><span>/dev/sda1 95054 55724 32162 64% /boot</span></span>
<span class="line"><span>tmpfs 807776 28 807748 1% /run/user/1000</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/04/df-command.png" alt=""></p><p>正如你所见，输出结果分为六列。我们来看一下每一列的含义。</p><ul><li><code>Filesystem</code> – Linux 系统中的文件系统</li><li><code>1K-blocks</code> – 文件系统的大小，用 1K 大小的块来表示。</li><li><code>Used</code> – 以 1K 大小的块所表示的已使用数量。</li><li><code>Available</code> – 以 1K 大小的块所表示的可用空间的数量。</li><li><code>Use%</code> – 文件系统中已使用的百分比。</li><li><code>Mounted on</code> – 已挂载的文件系统的挂载点。</li></ul><h4 id="_2、以人类友好格式显示文件系统硬盘空间使用情况" tabindex="-1">2、以人类友好格式显示文件系统硬盘空间使用情况 <a class="header-anchor" href="#_2、以人类友好格式显示文件系统硬盘空间使用情况" aria-label="Permalink to “2、以人类友好格式显示文件系统硬盘空间使用情况”">​</a></h4><p>在上面的示例中你可能已经注意到了，它使用 1K 大小的块为单位来表示使用情况，如果你以人类友好格式来显示它们，可以使用 <code>-h</code> 标志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -h</span></span>
<span class="line"><span>Filesystem Size Used Avail Use% Mounted on</span></span>
<span class="line"><span>dev 3.9G 0 3.9G 0% /dev</span></span>
<span class="line"><span>run 3.9G 1.1M 3.9G 1% /run</span></span>
<span class="line"><span>/dev/sda2 457G 409G 25G 95% /</span></span>
<span class="line"><span>tmpfs 3.9G 27M 3.9G 1% /dev/shm</span></span>
<span class="line"><span>tmpfs 3.9G 0 3.9G 0% /sys/fs/cgroup</span></span>
<span class="line"><span>tmpfs 3.9G 12M 3.9G 1% /tmp</span></span>
<span class="line"><span>/dev/loop0 83M 83M 0 100% /var/lib/snapd/snap/core/4327</span></span>
<span class="line"><span>/dev/sda1 93M 55M 32M 64% /boot</span></span>
<span class="line"><span>tmpfs 789M 28K 789M 1% /run/user/1000</span></span></code></pre></div><p>现在，在 <code>Size</code> 列和 <code>Avail</code> 列，使用情况是以 GB 和 MB 为单位来显示的。</p><h4 id="_3、仅以-mb-为单位来显示文件系统磁盘空间使用情况" tabindex="-1">3、仅以 MB 为单位来显示文件系统磁盘空间使用情况 <a class="header-anchor" href="#_3、仅以-mb-为单位来显示文件系统磁盘空间使用情况" aria-label="Permalink to “3、仅以 MB 为单位来显示文件系统磁盘空间使用情况”">​</a></h4><p>如果仅以 MB 为单位来显示文件系统磁盘空间使用情况，使用 <code>-m</code> 标志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -m</span></span>
<span class="line"><span>Filesystem 1M-blocks Used Available Use% Mounted on</span></span>
<span class="line"><span>dev 3939 0 3939 0% /dev</span></span>
<span class="line"><span>run 3945 2 3944 1% /run</span></span>
<span class="line"><span>/dev/sda2 467212 418742 24716 95% /</span></span>
<span class="line"><span>tmpfs 3945 26 3920 1% /dev/shm</span></span>
<span class="line"><span>tmpfs 3945 0 3945 0% /sys/fs/cgroup</span></span>
<span class="line"><span>tmpfs 3945 12 3933 1% /tmp</span></span>
<span class="line"><span>/dev/loop0 83 83 0 100% /var/lib/snapd/snap/core/4327</span></span>
<span class="line"><span>/dev/sda1 93 55 32 64% /boot</span></span>
<span class="line"><span>tmpfs 789 1 789 1% /run/user/1000</span></span></code></pre></div><h4 id="_4、列出节点而不是块的使用情况" tabindex="-1">4、列出节点而不是块的使用情况 <a class="header-anchor" href="#_4、列出节点而不是块的使用情况" aria-label="Permalink to “4、列出节点而不是块的使用情况”">​</a></h4><p>如下所示，我们可以通过使用 <code>-i</code> 标记来列出节点而不是块的使用情况。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -i</span></span>
<span class="line"><span>Filesystem Inodes IUsed IFree IUse% Mounted on</span></span>
<span class="line"><span>dev 1008304 439 1007865 1% /dev</span></span>
<span class="line"><span>run 1009720 649 1009071 1% /run</span></span>
<span class="line"><span>/dev/sda2 30392320 844035 29548285 3% /</span></span>
<span class="line"><span>tmpfs 1009720 86 1009634 1% /dev/shm</span></span>
<span class="line"><span>tmpfs 1009720 18 1009702 1% /sys/fs/cgroup</span></span>
<span class="line"><span>tmpfs 1009720 3008 1006712 1% /tmp</span></span>
<span class="line"><span>/dev/loop0 12829 12829 0 100% /var/lib/snapd/snap/core/4327</span></span>
<span class="line"><span>/dev/sda1 25688 390 25298 2% /boot</span></span>
<span class="line"><span>tmpfs 1009720 29 1009691 1% /run/user/1000</span></span></code></pre></div><h4 id="_5、显示文件系统类型" tabindex="-1">5、显示文件系统类型 <a class="header-anchor" href="#_5、显示文件系统类型" aria-label="Permalink to “5、显示文件系统类型”">​</a></h4><p>使用 <code>-T</code> 标志显示文件系统类型。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -T</span></span>
<span class="line"><span>Filesystem Type 1K-blocks Used Available Use% Mounted on</span></span>
<span class="line"><span>dev devtmpfs 4033216 0 4033216 0% /dev</span></span>
<span class="line"><span>run tmpfs 4038880 1120 4037760 1% /run</span></span>
<span class="line"><span>/dev/sda2 ext4 478425016 428790896 25308436 95% /</span></span>
<span class="line"><span>tmpfs tmpfs 4038880 31300 4007580 1% /dev/shm</span></span>
<span class="line"><span>tmpfs tmpfs 4038880 0 4038880 0% /sys/fs/cgroup</span></span>
<span class="line"><span>tmpfs tmpfs 4038880 11984 4026896 1% /tmp</span></span>
<span class="line"><span>/dev/loop0 squashfs 84096 84096 0 100% /var/lib/snapd/snap/core/4327</span></span>
<span class="line"><span>/dev/sda1 ext4 95054 55724 32162 64% /boot</span></span>
<span class="line"><span>tmpfs tmpfs 807776 28 807748 1% /run/user/1000</span></span></code></pre></div><p>正如你所见，现在出现了显示文件系统类型的额外的列（从左数的第二列）。</p><h4 id="_6、仅显示指定类型的文件系统" tabindex="-1">6、仅显示指定类型的文件系统 <a class="header-anchor" href="#_6、仅显示指定类型的文件系统" aria-label="Permalink to “6、仅显示指定类型的文件系统”">​</a></h4><p>我们可以限制仅列出某些文件系统。比如，只列出 ext4 文件系统。我们使用 <code>-t</code> 标志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -t ext4</span></span>
<span class="line"><span>Filesystem 1K-blocks Used Available Use% Mounted on</span></span>
<span class="line"><span>/dev/sda2 478425016 428790896 25308436 95% /</span></span>
<span class="line"><span>/dev/sda1 95054 55724 32162 64% /boot</span></span></code></pre></div><p>看到了吗？这个命令仅显示了 ext4 文件系统的磁盘空间使用情况。</p><h4 id="_7、不列出指定类型的文件系统" tabindex="-1">7、不列出指定类型的文件系统 <a class="header-anchor" href="#_7、不列出指定类型的文件系统" aria-label="Permalink to “7、不列出指定类型的文件系统”">​</a></h4><p>有时，我们可能需要从结果中去排除指定类型的文件系统。我们可以使用 <code>-x</code> 标记达到我们的目的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -x ext4</span></span>
<span class="line"><span>Filesystem 1K-blocks Used Available Use% Mounted on</span></span>
<span class="line"><span>dev 4033216 0 4033216 0% /dev</span></span>
<span class="line"><span>run 4038880 1120 4037760 1% /run</span></span>
<span class="line"><span>tmpfs 4038880 26116 4012764 1% /dev/shm</span></span>
<span class="line"><span>tmpfs 4038880 0 4038880 0% /sys/fs/cgroup</span></span>
<span class="line"><span>tmpfs 4038880 11984 4026896 1% /tmp</span></span>
<span class="line"><span>/dev/loop0 84096 84096 0 100% /var/lib/snapd/snap/core/4327</span></span>
<span class="line"><span>tmpfs 807776 28 807748 1% /run/user/1000</span></span></code></pre></div><p>上面的命令列出了除 ext4 类型以外的全部文件系统。</p><h4 id="_8、显示一个目录的磁盘使用情况" tabindex="-1">8、显示一个目录的磁盘使用情况 <a class="header-anchor" href="#_8、显示一个目录的磁盘使用情况" aria-label="Permalink to “8、显示一个目录的磁盘使用情况”">​</a></h4><p>去显示某个目录的硬盘空间使用情况以及它的挂载点，例如 <code>/home/sk/</code> 目录，可以使用如下的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -hT /home/sk/</span></span>
<span class="line"><span>Filesystem Type Size Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/sda2 ext4 457G 409G 25G 95% /</span></span></code></pre></div><p>这个命令显示文件系统类型、以人类友好格式显示已使用和可用磁盘空间、以及它的挂载点。如果你不想去显示文件系统类型，只需要忽略 <code>-t</code> 标志即可。</p><p>更详细的使用情况，请参阅 man 手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man df</span></span></code></pre></div><p>今天就到此这止！我希望对你有用。还有更多更好玩的东西即将奉上。请继续关注！</p><p>再见！</p><hr>`,43)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.ostechnix.com/the-df-command-tutorial-with-examples-for-beginners/"},{default:p(()=>[...s[0]||(s[0]=[a("https://www.ostechnix.com/the-df-command-tutorial-with-examples-for-beginners/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:p(()=>[...s[2]||(s[2]=[a("SK",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/qhwdw"},{default:p(()=>[...s[4]||(s[4]=[a("qhwdw",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=l(c,[["render",h]]);export{x as __pageData,y as default};
